//! Parity with sumy (https://github.com/miso-belica/sumy) and the `lexrank`
//! package (https://github.com/crabcamp/lexrank) on fixed texts.
//!
//! `fixtures/sumy_parity.rs` is generated by `fixtures/sumy_parity.py`,
//! which records the words and stems sumy used and each method's
//! per-sentence scores (or, for the greedy methods, selection order). The
//! generator's docstring lists where sumy is patched to follow the papers.
//! Scores must agree to 1e-9 (raw) or, for random walks, after normalizing
//! to sum 1 (sumy and the package do not normalize, and do not jump).

// Generated; regenerate rather than reformat.
#[rustfmt::skip]
#[allow(clippy::approx_constant)]
#[path = "fixtures/sumy_parity.rs"]
mod fixture;

use distil::summarize::{
    Edmundson, KlSum, LexRank, Lsa, Luhn, Reduction, SentenceExtractor, SumBasic, TextRank,
};
use distil::text::{Document, Token};
use std::collections::{HashMap, HashSet};

fn tokens(words: &[(&str, &str)]) -> Vec<Token> {
    words
        .iter()
        .map(|&(word, stem)| Token {
            word: word.to_string(),
            stem: stem.to_string(),
            pos: None,
        })
        .collect()
}

fn document(case: &fixture::Case) -> Document {
    Document::from_tokens(case.sentences.iter().map(|s| tokens(s)).collect())
}

/// Lowercased words as stems: sumy's KL-Sum does not stem.
fn unstemmed(case: &fixture::Case) -> Document {
    Document::from_tokens(
        case.sentences
            .iter()
            .map(|s| {
                s.iter()
                    .map(|&(w, _)| Token {
                        word: w.to_string(),
                        stem: w.to_lowercase(),
                        pos: None,
                    })
                    .collect()
            })
            .collect(),
    )
}

fn stopwords() -> HashSet<String> {
    fixture::STOPWORDS.iter().map(|s| s.to_string()).collect()
}

/// Scores in document order.
fn by_sentence(ranked: Vec<(usize, f64)>) -> Vec<f64> {
    let mut v = vec![f64::NAN; ranked.len()];
    for (i, s) in ranked {
        v[i] = s;
    }
    v
}

fn normalized(v: &[f64]) -> Vec<f64> {
    let s: f64 = v.iter().sum();
    v.iter().map(|x| x / s).collect()
}

fn assert_close(case: &str, method: &str, got: &[f64], want: &[f64], tol: f64) {
    assert_eq!(got.len(), want.len(), "{case} {method}: sentence count");
    for (i, (g, w)) in got.iter().zip(want).enumerate() {
        assert!(
            (g - w).abs() <= tol * w.abs().max(1.0),
            "{case} {method}: sentence {i}: distil {g}, sumy {w}\n  distil {got:?}\n  sumy   {want:?}"
        );
    }
}

fn scores(case: &fixture::Case, method: &str) -> Vec<f64> {
    let doc = document(case);
    let stop = stopwords();
    let rank = |e: &dyn SentenceExtractor| by_sentence(e.rank(&doc));
    match method {
        "luhn" => rank(&Luhn::new().with_stopwords(stop)),
        "edmundson" => {
            let heading = Document::from_tokens(vec![tokens(case.heading)]);
            rank(
                &Edmundson::new()
                    .with_stopwords(stop)
                    .with_bonus_words(fixture::BONUS)
                    .with_stigma_words(fixture::STIGMA)
                    .with_title(&heading)
                    .with_paragraphs(case.paragraphs.to_vec())
                    .with_weights(1.0, 1.0, 1.0, 1.0),
            )
        }
        "lsa" => rank(&Lsa::new().with_stopwords(stop)),
        "lsa_half" => rank(
            &Lsa::new()
                .with_stopwords(stop)
                .with_dimensions(case.lsa_half_dimensions),
        ),
        "reduction" => rank(&Reduction::new().with_stopwords(stop)),
        "textrank" => normalized(&TextRank::new().with_stopwords(stop).centrality(&doc)),
        "lexrank" => {
            let idf: HashMap<String, f64> = case
                .sumy_idf
                .iter()
                .map(|&(w, x)| (w.to_string(), x))
                .collect();
            normalized(
                &LexRank::new()
                    .with_stopwords(stop)
                    .with_jump(0.0)
                    .with_idf(idf, 0.0)
                    .centrality(&doc),
            )
        }
        other => panic!("no distil method for {other}"),
    }
}

#[test]
fn scoring_methods_match_sumy() {
    for case in fixture::CASES {
        for &(method, want) in case.scores {
            let want = match method {
                "textrank" | "lexrank" => normalized(want),
                _ => want.to_vec(),
            };
            assert_close(case.name, method, &scores(case, method), &want, 1e-9);
        }
    }
}

#[test]
fn greedy_methods_match_sumy_selection_order() {
    for case in fixture::CASES {
        for &(method, want) in case.orders {
            let ranked = match method {
                "sumbasic" => SumBasic::new()
                    .with_stopwords(stopwords())
                    .with_top_word_rule(false)
                    .rank(&document(case)),
                "kl" => KlSum::new()
                    .with_stopwords(stopwords())
                    .rank(&unstemmed(case)),
                other => panic!("no distil method for {other}"),
            };
            let got: Vec<usize> = ranked.iter().map(|x| x.0).collect();
            assert_eq!(got, want, "{} {method}", case.name);
        }
    }
}

#[test]
fn lexrank_matches_the_lexrank_package() {
    let stop: HashSet<String> = fixture::LEXRANK_STOPWORDS
        .iter()
        .map(|s| s.to_string())
        .collect();
    for case in fixture::LEXRANK_CASES {
        let doc = Document::from_tokens(
            case.tokens
                .iter()
                .map(|s| {
                    s.iter()
                        .map(|&t| Token {
                            word: t.to_string(),
                            stem: t.to_string(),
                            pos: None,
                        })
                        .collect()
                })
                .collect(),
        );
        let idf: HashMap<String, f64> = case.idf.iter().map(|&(w, x)| (w.to_string(), x)).collect();
        let base = LexRank::new()
            .with_stopwords(stop.clone())
            .with_jump(0.0)
            .with_idf(idf, fixture::LEXRANK_UNSEEN_IDF);
        let threshold = base.clone().with_threshold(0.1).centrality(&doc);
        assert_close(
            case.name,
            "threshold",
            &threshold,
            &normalized(case.threshold),
            1e-9,
        );
        let continuous = base.continuous().centrality(&doc);
        assert_close(
            case.name,
            "continuous",
            &continuous,
            &normalized(case.continuous),
            1e-9,
        );
    }
}
